window.RP_SESSION={"id":"S-0edf7b35fc71","messages":[{"id":"RP-0117543","time":"2026-04-19T10:39:00+09:00","room":"RP","name":"발락","profile":"발락","identity":"reviewed","type":"dialogue","body":"먼 곳에서 울리는 개짖는 소리가 잠을 깨웠다. 근처에서 공사라도 있는지 정으로 돌을 깨는 소리가 그제야 뒤를 따라 귓바퀴로 굴러들어온다. \n\n느즈막히 아침을 마주한 그는 지난 밤 신세를 진 바닥에서 비척거리며 일어났다. 여관 방이야 결국 사면이 안전한 것에 의의가 있는법. 그러면 등배기고 불편한 침대 위에서 무리해서 잘 필요는 없으리라. \n\n그물로 덮어 팔뚝과 연결해둔 짐으로부터 싸구려 와인 섞은 가죽물통을 끄집어낸 그는 벌컥거리며 목을 축이고서는 주섬주섬 짐을 챙겨 밑으로 내려온다. 지난 밤 머리가 높아 올라오다 부닥친 천장 한 귀퉁이가 보였다. 괜시리 기분이 상해 꿍얼거리다 두 손으로 얼굴을 가볍게 툭툭 치고서야 입가에 미소가 자연스럽게 피어올랐다.\n\n\"아주 좋아. 오늘도 상쾌한 날이야.\"\n\n낄낄거리며 밑으로 내려온 그는 여관주인이 뭐라 하기도 전에 스튜냄비 앞으로 가선 냄비에 걸린 국자를 잡고 가방에서 꺼낸 자기 그릇에 그 걸죽하고 거무튀튀한 것을 한가득 퍼올리며 말했다.\n\n\"","characters":["P-7140c14e5809"]},{"id":"RP-0117545","time":"2026-04-19T14:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0117546","time":"2026-04-19T14:30:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
